-- Stage 5: audited task workflow, review, templates, and manual idempotent recurrence.
begin;

update public.tasks set status = case when status in ('OPEN', 'WAITING') then 'TODO' else status end;
alter table public.tasks drop constraint if exists tasks_status_check;
alter table public.tasks add constraint tasks_status_check check (status in ('TODO', 'IN_PROGRESS', 'IN_REVIEW', 'COMPLETED', 'CANCELLED'));
alter table public.tasks alter column status set default 'TODO';
alter table public.tasks add column if not exists due_at timestamptz;
alter table public.tasks add column if not exists recurrence_key text;
alter table public.tasks add column if not exists period_start date;
alter table public.tasks add column if not exists period_end date;
alter table public.tasks add column if not exists review_requested_at timestamptz;
alter table public.tasks add column if not exists reviewed_at timestamptz;
alter table public.tasks add column if not exists reviewed_by_profile_id uuid;
alter table public.tasks add column if not exists completion_note text;
alter table public.tasks add constraint tasks_reviewer_fk foreign key (firm_id, reviewed_by_profile_id) references public.firm_memberships(firm_id, profile_id) on delete restrict;
create unique index if not exists tasks_firm_recurrence_key_unique on public.tasks (firm_id, recurrence_key) where recurrence_key is not null;
create index if not exists tasks_firm_status_owner_due_at_idx on public.tasks (firm_id, status, owner_profile_id, due_at);

alter table public.task_templates add column if not exists recurrence_frequency text not null default 'NONE';
alter table public.task_templates add column if not exists default_due_offset_days integer not null default 0;
alter table public.task_templates add constraint task_templates_recurrence_frequency_check check (recurrence_frequency in ('NONE', 'MONTHLY', 'QUARTERLY', 'ANNUAL'));
alter table public.task_templates add constraint task_templates_due_offset_check check (default_due_offset_days between -366 and 366);

create table if not exists public.task_template_checklist_items (
  id uuid primary key default gen_random_uuid(), firm_id uuid not null, template_id uuid not null, position integer not null default 0 check (position >= 0), label text not null check (char_length(trim(label)) between 1 and 240), created_at timestamptz not null default timezone('utc', now()),
  unique (firm_id, id), foreign key (firm_id) references public.firms(id) on delete restrict, foreign key (firm_id, template_id) references public.task_templates(firm_id, id) on delete cascade
);
create table if not exists public.task_history (
  id uuid primary key default gen_random_uuid(), firm_id uuid not null, task_id uuid not null, actor_profile_id uuid not null, event_type text not null check (event_type ~ '^[a-z][a-z0-9_.-]{1,80}$'), from_status text, to_status text, note text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default timezone('utc', now()),
  foreign key (firm_id) references public.firms(id) on delete restrict, foreign key (firm_id, task_id) references public.tasks(firm_id, id) on delete restrict, foreign key (firm_id, actor_profile_id) references public.firm_memberships(firm_id, profile_id) on delete restrict
);
create table if not exists public.task_document_requests (
  id uuid primary key default gen_random_uuid(), firm_id uuid not null, task_id uuid not null, label text not null check (char_length(trim(label)) between 1 and 240), status text not null default 'REQUESTED' check (status in ('REQUESTED', 'RECEIVED')), requested_by_profile_id uuid not null, received_at timestamptz, created_at timestamptz not null default timezone('utc', now()), updated_at timestamptz not null default timezone('utc', now()), archived_at timestamptz,
  unique (firm_id, id), foreign key (firm_id) references public.firms(id) on delete restrict, foreign key (firm_id, task_id) references public.tasks(firm_id, id) on delete restrict, foreign key (firm_id, requested_by_profile_id) references public.firm_memberships(firm_id, profile_id) on delete restrict
);
create index if not exists task_history_task_created_idx on public.task_history (firm_id, task_id, created_at desc);
create index if not exists task_document_requests_task_idx on public.task_document_requests (firm_id, task_id, status, archived_at);
create trigger task_document_requests_set_updated_at before update on public.task_document_requests for each row execute function public.set_updated_at();

alter table public.task_template_checklist_items enable row level security; alter table public.task_template_checklist_items force row level security;
alter table public.task_history enable row level security; alter table public.task_history force row level security;
alter table public.task_document_requests enable row level security; alter table public.task_document_requests force row level security;
create policy template_checklist_select on public.task_template_checklist_items for select to authenticated using (public.is_firm_member(firm_id));
create policy task_history_select on public.task_history for select to authenticated using (public.is_firm_member(firm_id));
create policy task_document_requests_select on public.task_document_requests for select to authenticated using (public.is_firm_member(firm_id));

drop policy if exists tasks_insert_member on public.tasks; drop policy if exists tasks_update_participant on public.tasks; drop policy if exists tasks_delete_manager on public.tasks;
drop policy if exists checklist_insert_member on public.task_checklist_items; drop policy if exists checklist_update_member on public.task_checklist_items; drop policy if exists checklist_delete_manager on public.task_checklist_items;
drop policy if exists comments_insert_author on public.task_comments; drop policy if exists comments_update_author on public.task_comments; drop policy if exists comments_delete_author on public.task_comments;

create or replace function public.task_active_membership() returns public.firm_memberships language plpgsql security definer set search_path = public, auth as $$ declare m public.firm_memberships; begin m := public.client_active_membership(); return m; end; $$;
create or replace function public.task_member_is_active(p_firm uuid, p_profile uuid) returns boolean language sql stable security definer set search_path = public as $$ select p_profile is null or exists (select 1 from public.firm_memberships where firm_id = p_firm and profile_id = p_profile and status = 'ACTIVE' and archived_at is null); $$;
create or replace function public.task_write_history(p_firm uuid, p_task uuid, p_event text, p_from text default null, p_to text default null, p_note text default null, p_metadata jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path = public, auth as $$ begin insert into public.task_history(firm_id, task_id, actor_profile_id, event_type, from_status, to_status, note, metadata) values(p_firm,p_task,auth.uid(),p_event,p_from,p_to,nullif(trim(p_note),''),p_metadata); insert into public.audit_events(firm_id,actor_profile_id,actor_user_id,action,entity_table,entity_id,metadata) values(p_firm,auth.uid(),auth.uid(),p_event,'tasks',p_task,p_metadata); end; $$;

create or replace function public.create_task_workflow(p_title text, p_client_id uuid, p_service_id uuid, p_owner uuid, p_assignee uuid, p_reviewer uuid, p_priority text, p_due_at timestamptz, p_description text default null, p_template_id uuid default null) returns uuid language plpgsql security definer set search_path = public, auth as $$
declare m public.firm_memberships; task_id uuid := gen_random_uuid();
begin m := public.task_active_membership();
 if nullif(trim(p_title),'') is null then raise exception 'task title is required'; end if;
 if p_priority not in ('LOW','MEDIUM','HIGH','URGENT') then raise exception 'invalid task priority'; end if;
 if p_client_id is not null and not exists(select 1 from public.clients where id=p_client_id and firm_id=m.firm_id and archived_at is null) then raise exception 'client is unavailable or archived' using errcode='P0002'; end if;
 if p_service_id is not null and not exists(select 1 from public.services where id=p_service_id and firm_id=m.firm_id and archived_at is null and is_active) then raise exception 'service is unavailable' using errcode='P0002'; end if;
 if not public.task_member_is_active(m.firm_id,p_owner) or not public.task_member_is_active(m.firm_id,p_assignee) or not public.task_member_is_active(m.firm_id,p_reviewer) then raise exception 'selected task member is no longer active'; end if;
 if p_reviewer is not null and p_reviewer = coalesce(p_assignee,p_owner) and coalesce((select (settings->>'allow_self_review')::boolean from public.firms where id=m.firm_id),false) is false then raise exception 'self-review is disabled for this firm' using errcode='42501'; end if;
 insert into public.tasks(id,firm_id,client_id,service_id,template_id,owner_profile_id,assignee_profile_id,reviewer_profile_id,created_by_profile_id,title,description,status,priority,due_at,due_date) values(task_id,m.firm_id,p_client_id,p_service_id,p_template_id,p_owner,p_assignee,p_reviewer,auth.uid(),trim(p_title),nullif(trim(p_description),''),'TODO',p_priority,p_due_at,case when p_due_at is null then null else (p_due_at at time zone coalesce((select timezone from public.firms where id=m.firm_id),'Asia/Kolkata'))::date end);
 if p_template_id is not null then insert into public.task_checklist_items(firm_id,task_id,position,label) select m.firm_id,task_id,position,label from public.task_template_checklist_items where firm_id=m.firm_id and template_id=p_template_id order by position; end if;
 perform public.task_write_history(m.firm_id,task_id,'task.created',null,'TODO',null,jsonb_build_object('client_id',p_client_id,'template_id',p_template_id)); return task_id; end; $$;

create or replace function public.transition_task_workflow(p_task_id uuid, p_expected_updated_at timestamptz, p_to_status text, p_note text default null) returns void language plpgsql security definer set search_path=public,auth as $$
declare m public.firm_memberships; t public.tasks; manager boolean; allowed boolean := false;
begin m:=public.task_active_membership(); select * into t from public.tasks where id=p_task_id and firm_id=m.firm_id and archived_at is null for update; if t.id is null then raise exception 'task not found' using errcode='P0002'; end if; if t.updated_at is distinct from p_expected_updated_at then raise exception 'This task changed elsewhere. Refresh and review the latest version.' using errcode='40001'; end if; manager:=public.has_firm_role(m.firm_id,array['OWNER','PARTNER','MANAGER']::public.firm_role[]);
 if p_to_status='IN_PROGRESS' and t.status='TODO' then allowed:= manager or auth.uid() in (t.owner_profile_id,t.assignee_profile_id); end if;
 if p_to_status='IN_REVIEW' and t.status='IN_PROGRESS' then allowed:= manager or auth.uid() in (t.owner_profile_id,t.assignee_profile_id); if exists(select 1 from public.task_checklist_items where firm_id=m.firm_id and task_id=t.id and archived_at is null and not is_completed) then raise exception 'complete every checklist item before requesting review'; end if; end if;
 if p_to_status='COMPLETED' and t.status='IN_REVIEW' then allowed:=manager or auth.uid()=t.reviewer_profile_id; if t.reviewer_profile_id is null then raise exception 'a reviewer is required before approval'; end if; if auth.uid()=coalesce(t.assignee_profile_id,t.owner_profile_id) and coalesce((select (settings->>'allow_self_review')::boolean from public.firms where id=m.firm_id),false) is false then raise exception 'self-review is disabled for this firm' using errcode='42501'; end if; end if;
 if p_to_status='IN_PROGRESS' and t.status='IN_REVIEW' then allowed:=manager or auth.uid()=t.reviewer_profile_id; if nullif(trim(p_note),'') is null then raise exception 'a return-to-work comment is required'; end if; end if;
 if not allowed then raise exception 'invalid task transition or permission denied' using errcode='42501'; end if;
 update public.tasks set status=p_to_status, review_requested_at=case when p_to_status='IN_REVIEW' then timezone('utc',now()) else review_requested_at end, reviewed_at=case when p_to_status in ('COMPLETED','IN_PROGRESS') and t.status='IN_REVIEW' then timezone('utc',now()) else reviewed_at end, reviewed_by_profile_id=case when p_to_status in ('COMPLETED','IN_PROGRESS') and t.status='IN_REVIEW' then auth.uid() else reviewed_by_profile_id end, completed_at=case when p_to_status='COMPLETED' then timezone('utc',now()) else null end, completion_note=case when p_to_status='COMPLETED' then nullif(trim(p_note),'') else completion_note end where id=t.id;
 if t.status='IN_REVIEW' and nullif(trim(p_note),'') is not null then insert into public.task_comments(firm_id,task_id,author_profile_id,body) values(m.firm_id,t.id,auth.uid(),trim(p_note)); end if; perform public.task_write_history(m.firm_id,t.id,case when p_to_status='COMPLETED' then 'task.review_approved' when t.status='IN_REVIEW' then 'task.review_returned' else 'task.status_changed' end,t.status,p_to_status,p_note); end; $$;

create or replace function public.add_task_comment_workflow(p_task_id uuid,p_body text) returns uuid language plpgsql security definer set search_path=public,auth as $$ declare m public.firm_memberships; comment_id uuid; begin m:=public.task_active_membership(); if not exists(select 1 from public.tasks where id=p_task_id and firm_id=m.firm_id and archived_at is null) then raise exception 'task not found' using errcode='P0002'; end if; insert into public.task_comments(firm_id,task_id,author_profile_id,body) values(m.firm_id,p_task_id,auth.uid(),trim(p_body)) returning id into comment_id; perform public.task_write_history(m.firm_id,p_task_id,'task.comment_added',null,null,null); return comment_id; end; $$;
create or replace function public.set_task_checklist_item(p_task_id uuid,p_item_id uuid,p_completed boolean) returns void language plpgsql security definer set search_path=public,auth as $$ declare m public.firm_memberships; begin m:=public.task_active_membership(); update public.task_checklist_items set is_completed=p_completed,completed_by_profile_id=case when p_completed then auth.uid() else null end where id=p_item_id and task_id=p_task_id and firm_id=m.firm_id and archived_at is null; if not found then raise exception 'checklist item not found' using errcode='P0002'; end if; perform public.task_write_history(m.firm_id,p_task_id,'task.checklist_updated',null,null,null,jsonb_build_object('item_id',p_item_id,'completed',p_completed)); end; $$;
create or replace function public.save_task_document_request(p_task_id uuid,p_request_id uuid,p_label text,p_status text default 'REQUESTED') returns uuid language plpgsql security definer set search_path=public,auth as $$ declare m public.firm_memberships; result uuid; begin m:=public.task_active_membership(); if not exists(select 1 from public.tasks where id=p_task_id and firm_id=m.firm_id and archived_at is null) then raise exception 'task not found' using errcode='P0002'; end if; if p_status not in ('REQUESTED','RECEIVED') then raise exception 'invalid document request status'; end if; if p_request_id is null then insert into public.task_document_requests(firm_id,task_id,label,status,requested_by_profile_id,received_at) values(m.firm_id,p_task_id,trim(p_label),p_status,auth.uid(),case when p_status='RECEIVED' then timezone('utc',now()) end) returning id into result; else update public.task_document_requests set label=trim(p_label),status=p_status,received_at=case when p_status='RECEIVED' then coalesce(received_at,timezone('utc',now())) else null end where id=p_request_id and task_id=p_task_id and firm_id=m.firm_id and archived_at is null returning id into result; end if; if result is null or nullif(trim(p_label),'') is null then raise exception 'document request label is required'; end if; perform public.task_write_history(m.firm_id,p_task_id,'task.document_request_saved',null,null,null,jsonb_build_object('request_id',result,'status',p_status)); return result; end; $$;
create or replace function public.create_recurring_task_for_period(p_template_id uuid,p_client_id uuid,p_period_start date,p_period_end date) returns uuid language plpgsql security definer set search_path=public,auth as $$ declare m public.firm_memberships; tpl public.task_templates; k text; task_id uuid; due timestamptz; begin m:=public.task_active_membership(); if p_period_end<p_period_start then raise exception 'period end must not precede period start'; end if; select * into tpl from public.task_templates where id=p_template_id and firm_id=m.firm_id and is_active and archived_at is null for update; if tpl.id is null or tpl.recurrence_frequency='NONE' then raise exception 'active recurring template not found'; end if; if not exists(select 1 from public.clients where id=p_client_id and firm_id=m.firm_id and archived_at is null) then raise exception 'client is unavailable or archived' using errcode='P0002'; end if; k:=p_template_id::text||':'||p_client_id::text||':'||p_period_start::text; select id into task_id from public.tasks where firm_id=m.firm_id and recurrence_key=k; if task_id is not null then return task_id; end if; due:=((p_period_end + tpl.default_due_offset_days)::timestamp at time zone coalesce((select timezone from public.firms where id=m.firm_id),'Asia/Kolkata')); task_id:=public.create_task_workflow(tpl.name,p_client_id,tpl.service_id,null,null,null,tpl.default_priority,due,tpl.description,tpl.id); update public.tasks set recurrence_key=k,period_start=p_period_start,period_end=p_period_end where id=task_id; perform public.task_write_history(m.firm_id,task_id,'task.recurrence_generated',null,'TODO',null,jsonb_build_object('recurrence_key',k)); return task_id; exception when unique_violation then select id into task_id from public.tasks where firm_id=m.firm_id and recurrence_key=k; return task_id; end; $$;

revoke all on function public.task_active_membership(), public.task_member_is_active(uuid,uuid), public.task_write_history(uuid,uuid,text,text,text,text,jsonb), public.create_task_workflow(text,uuid,uuid,uuid,uuid,uuid,text,timestamptz,text,uuid), public.transition_task_workflow(uuid,timestamptz,text,text), public.add_task_comment_workflow(uuid,text), public.set_task_checklist_item(uuid,uuid,boolean), public.create_recurring_task_for_period(uuid,uuid,date,date) from public;
revoke all on function public.save_task_document_request(uuid,uuid,text,text) from public;
grant execute on function public.create_task_workflow(text,uuid,uuid,uuid,uuid,uuid,text,timestamptz,text,uuid), public.transition_task_workflow(uuid,timestamptz,text,text), public.add_task_comment_workflow(uuid,text), public.set_task_checklist_item(uuid,uuid,boolean), public.save_task_document_request(uuid,uuid,text,text), public.create_recurring_task_for_period(uuid,uuid,date,date) to authenticated,service_role;
commit;
